<div class="content events-content"><section class="title"><div><span class="eyebrow">CATÁLOGO</span><h1>GESTIÓN DE <em>EVENTOS.</em></h1><p>Crea, publica y organiza los eventos que aparecen en la tienda.</p></div><a class="btn btn-primary" href="<?=url('admin/eventos')?>">+ NUEVO EVENTO</a></section><?php if(!empty($_SESSION['success'])):?><div class="flash success"><?=htmlspecialchars($_SESSION['success']);unset($_SESSION['success']);?></div><?php endif;?><?php if(!empty($_SESSION['error'])):?><div class="flash error"><?=htmlspecialchars($_SESSION['error']);unset($_SESSION['error']);?></div><?php endif;?><div class="events-admin-grid"><form class="panel event-form" method="post" action="<?=url('admin/eventos/guardar')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$selected['id']??''?>"><div class="panel-head"><div><span class="eyebrow"><?=$selected?'EDITAR':'NUEVO'?></span><h2><?=$selected?'ACTUALIZAR EVENTO':'CREAR EVENTO'?></h2></div></div><label>NOMBRE DEL EVENTO<input name="name" required value="<?=htmlspecialchars($selected['name']??'')?>" placeholder="Ej. Trail Volcán Antuco"></label><div class="two-fields"><label>DISCIPLINA<input name="sport" required value="<?=htmlspecialchars($selected['sport']??'')?>" placeholder="Running, fútbol, ciclismo..."></label><label>FECHA<input name="event_date" type="date" required value="<?=htmlspecialchars($selected['event_date']??date('Y-m-d'))?>"></label></div><label>UBICACIÓN<input name="location" value="<?=htmlspecialchars($selected['location']??'')?>" placeholder="Ciudad o recinto"></label><label>ESTADO<select name="status"><option value="draft" <?=($selected['status']??'')==='draft'?'selected':''?>>Borrador · No visible</option><option value="published" <?=($selected['status']??'published')==='published'?'selected':''?>>Publicado · Visible en portada</option><option value="archived" <?=($selected['status']??'')==='archived'?'selected':''?>>Archivado</option></select></label><div class="event-form-actions"><?php if($selected):?><a class="btn btn-secondary" href="<?=url('admin/eventos')?>">CANCELAR</a><?php endif;?><button class="btn btn-primary">GUARDAR EVENTO →</button></div></form><section class="panel events-list"><div class="panel-head"><div><span class="eyebrow">REGISTROS</span><h2>EVENTOS CREADOS</h2></div><span class="result-count"><?=count($events)?> EVENTOS</span></div><div class="event-admin-cards"><?php foreach($events as $e):?><article><div class="event-cover"><?php if($e['preview_path']):?><img src="<?=preview_url(['id'=>$e['cover_id'],'preview_path'=>$e['preview_path']])?>"><?php else:?><span>SIN FOTOS</span><?php endif;?></div><div class="event-info"><small><?=htmlspecialchars(strtoupper($e['sport']))?> · <?=date('d/m/Y',strtotime($e['event_date']))?></small><h3><?=htmlspecialchars($e['name'])?></h3><p><?=htmlspecialchars($e['location']??'Sin ubicación')?> · <?=$e['photos_count']?> fotos · <?=$e['sets_count']?> sets</p><em class="event-status <?=$e['status']?>"><?=strtoupper($e['status'])?></em></div><div class="event-actions"><a class="btn btn-edit" href="<?=url('admin/eventos?id='.$e['id'])?>">EDITAR</a><form method="post" action="<?=url('admin/eventos/estado')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$e['id']?>"><input type="hidden" name="status" value="<?=$e['status']==='published'?'draft':'published'?>"><button class="btn btn-toggle"><?=$e['status']==='published'?'OCULTAR':'PUBLICAR'?></button></form><form method="post" action="<?=url('admin/eventos/eliminar')?>" onsubmit="return confirm('¿Eliminar o archivar este evento?')"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$e['id']?>"><button class="btn btn-danger">ELIMINAR</button></form></div></article><?php endforeach;?></div></section></div></div>
